e-lt"><?=html_escape($lesson['context_label'])?></span></span><?php if($can_edit):?><a class="btn btn-sm btn-outline-secondary" href="<?=base_url('learn-english-course/toggle/lesson/'.$lesson['id'])?>"><?=$lesson['is_active']?'Aktif':'Nonaktif'?></a><?php endif?></div><?php endforeach?></div><?php endforeach?><div class="alert alert-info mb-0"><i class="ti ti-certificate me-1"></i>Tes level: <strong><?=html_escape($level['test']['title']??'-')?></strong> · batas lulus <?=intval($level['pass_score'])?></div></div></div></div><?php endforeach?></div></div></div>
